import{_ as e,o as i,c as r,a2 as t}from"./chunks/framework.XctAhZuT.js";const u=JSON.parse('{"title":"常见问题","description":"不需要。核心课程、复习和学习状态在本地运行。","frontmatter":{"description":"不需要。核心课程、复习和学习状态在本地运行。"},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1787830168000}'),o={name:"guide/faq.md"};function n(s,a,l,h,d,c){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="turna-是否需要账号" tabindex="-1">Turna 是否需要账号 <a class="header-anchor" href="#turna-是否需要账号" aria-label="Permalink to &quot;Turna 是否需要账号&quot;">​</a></h2><p>不需要。核心课程、复习和学习状态在本地运行。</p><h2 id="没有网络能否学习" tabindex="-1">没有网络能否学习 <a class="header-anchor" href="#没有网络能否学习" aria-label="Permalink to &quot;没有网络能否学习&quot;">​</a></h2><p>可以。已安装课程和本地复习不依赖网络。外部 AI、远程卡片资源和主动更新需要网络。</p><h2 id="web-产品主页是否就是学习应用" tabindex="-1">Web 产品主页是否就是学习应用 <a class="header-anchor" href="#web-产品主页是否就是学习应用" aria-label="Permalink to &quot;Web 产品主页是否就是学习应用&quot;">​</a></h2><p>不是。TurnaWeb 提供产品页和技术文档。学习客户端是 Flutter 应用。</p><h2 id="为什么有两套-fsrs" tabindex="-1">为什么有两套 FSRS <a class="header-anchor" href="#为什么有两套-fsrs" aria-label="Permalink to &quot;为什么有两套 FSRS&quot;">​</a></h2><p>课程项目由 Dart FSRS 调度。Official Anki 卡由 Official Anki scheduler 调度。两者算法概念相近，但状态所有者不同。</p><h2 id="能否把-official-anki-卡静默改用-turna-fsrs" tabindex="-1">能否把 Official Anki 卡静默改用 Turna FSRS <a class="header-anchor" href="#能否把-official-anki-卡静默改用-turna-fsrs" aria-label="Permalink to &quot;能否把 Official Anki 卡静默改用 Turna FSRS&quot;">​</a></h2><p>不能。Official runtime 不可用时应明确关闭相关功能，避免分叉复习历史。</p><h2 id="支持哪些-anki-文件" tabindex="-1">支持哪些 Anki 文件 <a class="header-anchor" href="#支持哪些-anki-文件" aria-label="Permalink to &quot;支持哪些 Anki 文件&quot;">​</a></h2><p>Android 生产导入合同以 <code>.apkg</code> 为主。<code>.colpkg</code> 当前不作为正式导入路径。</p><h2 id="能否导入-librelingo-课程" tabindex="-1">能否导入 LibreLingo 课程 <a class="header-anchor" href="#能否导入-librelingo-课程" aria-label="Permalink to &quot;能否导入 LibreLingo 课程&quot;">​</a></h2><p>可以，但不直接读 YAML。先用离线工具把 LibreLingo 课程转成 <code>.turnapack</code>（见<a href="/docs/authoring/course-pack">外部课程包</a>），再到「课程管理 → 导入课程包」安装（见<a href="/docs/guide/course-pack">导入课程包</a>）。</p><h2 id="为什么复杂-anki-卡片没有网络" tabindex="-1">为什么复杂 Anki 卡片没有网络 <a class="header-anchor" href="#为什么复杂-anki-卡片没有网络" aria-label="Permalink to &quot;为什么复杂 Anki 卡片没有网络&quot;">​</a></h2><p>卡片网络默认关闭。HTML 模板可能包含未知脚本和远程请求。用户可以按策略显式允许，但不应默认开放。</p><h2 id="ai-是否必需" tabindex="-1">AI 是否必需 <a class="header-anchor" href="#ai-是否必需" aria-label="Permalink to &quot;AI 是否必需&quot;">​</a></h2><p>不是。未配置 AI 时，课程、FSRS、Anki 正式复习和本地课程片段答疑仍可工作。</p><h2 id="api-key-保存在哪里" tabindex="-1">API key 保存在哪里 <a class="header-anchor" href="#api-key-保存在哪里" aria-label="Permalink to &quot;API key 保存在哪里&quot;">​</a></h2><p>原生平台使用可用的安全存储。缺少安全存储能力的平台只在当前会话保留，并显示限制。</p><h2 id="sqlite-是课程真理源吗" tabindex="-1">SQLite 是课程真理源吗 <a class="header-anchor" href="#sqlite-是课程真理源吗" aria-label="Permalink to &quot;SQLite 是课程真理源吗&quot;">​</a></h2><p>不是。课程 JSON 是真理源，SQLite 是应用启动后生成的缓存。学习进度和复习状态则是用户本地状态。</p><h2 id="修改-json-后为什么应用没有变化" tabindex="-1">修改 JSON 后为什么应用没有变化 <a class="header-anchor" href="#修改-json-后为什么应用没有变化" aria-label="Permalink to &quot;修改 JSON 后为什么应用没有变化&quot;">​</a></h2><p>检查 <code>index.json</code> 的内容版本。语义变化需要增加版本以触发重新导入。</p><h2 id="可以直接修改数据库来编辑课程吗" tabindex="-1">可以直接修改数据库来编辑课程吗 <a class="header-anchor" href="#可以直接修改数据库来编辑课程吗" aria-label="Permalink to &quot;可以直接修改数据库来编辑课程吗&quot;">​</a></h2><p>不可以。编辑器、CLI 和人工修改都应写课程 JSON，再通过校验与版本导入。</p><h2 id="清缓存会删除学习进度吗" tabindex="-1">清缓存会删除学习进度吗 <a class="header-anchor" href="#清缓存会删除学习进度吗" aria-label="Permalink to &quot;清缓存会删除学习进度吗&quot;">​</a></h2><p>正常的缓存清理只删除可再生成的预渲染与 AI 缓存。清除应用数据、数据库或牌组是不同操作。</p><h2 id="docs-页面如何复制" tabindex="-1">docs 页面如何复制 <a class="header-anchor" href="#docs-页面如何复制" aria-label="Permalink to &quot;docs 页面如何复制&quot;">​</a></h2><p>每篇正文顶部有“复制全文”。按钮复制当前页面的 Markdown 原文，包括标题、表格、代码块和链接，不包含站点导航。</p><h2 id="如何构建文档子目录" tabindex="-1">如何构建文档子目录 <a class="header-anchor" href="#如何构建文档子目录" aria-label="Permalink to &quot;如何构建文档子目录&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SITE_BASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/turna-web/</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>文档资源会生成到 <code>/turna-web/docs/</code> 对应路径。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/getting-started">快速开始</a></li><li><a href="/docs/guide/troubleshooting">故障排查</a></li><li><a href="/docs/developer/glossary">术语表</a></li></ul>',36)])])}const k=e(o,[["render",n]]);export{u as __pageData,k as default};
